TraceSeries _series(String name, String unit, Float64List values) =>
    TraceSeries(
      channelName: name,
      unit: unit,
      frequencyHz: 5,
      valueColumn: 'value',
      times: _times,
      lows: values,
      highs: values,
    );

/// The lap as `lapTelemetryProvider` would resolve it.
LapTelemetry sebringLapTelemetry() => LapTelemetry(
      lap: sebringLap(),
      startSeconds: sebringLapStartSeconds,
      endSeconds: sebringLapEndSeconds,
      channels: {
        'Ground Speed': _series('Ground Speed', 'km/h', _speed),
        'Throttle Pos': _series('Throttle Pos', '%', _throttle),
        'Brake Pos': _series('Brake Pos', '%', _brake),
        'Steering Pos': _series('Steering Pos', '%', _steering),
        'Engine RPM': _series('Engine RPM', 'RPM', _rpm),
      },
      gear: StepSeries.fromRows(_gearRows, eventName: 'Gear'),
      lapDistance: _series('Lap Dist', 'm', _lapDistance),
      latitude: _series('GPS Latitude', 'deg', _latitude),
      longitude: _series('GPS Longitude', 'deg', _longitude),
      sectorBoundaries: _sectorCrossings,
    );

Lap sebringLap() => Lap(
      index: sebringLapIndex,
      startSeconds: sebringLapStartSeconds,
      endSeconds: sebringLapEndSeconds,
      lapTimeSeconds: sebringLapTimeSeconds,
      sectors: SectorTimes.fromCumulative(
        sector1: sebringLapSector1,
        sector2Cumulative: sebringLapSector2Cumulative,
        lapTimeSeconds: sebringLapTimeSeconds,
      ),
    );
